# More detailed analysis
# Build adjacency graph
from collections import defaultdict

adj = defaultdict(set)
positions = [(0, 2), (0, 8), (1, 1), (1, 3), (1, 7), (2, 0), (2, 4), (2, 6), (3, 5)]

for i, p1 in enumerate(positions):
    for j, p2 in enumerate(positions):
        if i >= j:
            continue
        if abs(p1[0] - p2[0]) == 1 and abs(p1[1] - p2[1]) == 1:
            adj[p1].add(p2)
            adj[p2].add(p1)

print("Adjacency list:", dict(adj))

# Find connected components
visited = set()
components = []

for p in positions:
    if p in visited:
        continue
    # BFS
    comp = []
    queue = [p]
    while queue:
        curr = queue.pop(0)
        if curr in visited:
            continue
        visited.add(curr)
        comp.append(curr)
        for n in adj[curr]:
            if n not in visited:
                queue.append(n)
    components.append(comp)

print("Connected components:", components)

